shape1_rightmost = max(c for r in range(1, 5) for c in range(10) if test_input[r][c] == 5)
shape2_leftmost = min(c for r in range(7, 10) for c in range(10) if test_input[r][c] == 5)
shape2_rightmost = max(c for r in range(7, 10) for c in range(10) if test_input[r][c] == 5)

